app Shop
model Product { id integer name text price integer }
type CartLine { productId integer price integer quantity integer }
component ProductRow { button "Add" on add with product from product }
component CartRow { button "More" on more with line from line }
component CartSummary { show total of cart by price times quantity }
page Cart { state products list<Product> = [] state cart list<CartLine> persisted in local storage event add(product Product) appends product as CartLine { productId: product.id, price: product.price, quantity: 1 } to cart event more(line CartLine) increases quantity of line in cart for each product in products show ProductRow for each line in cart show CartRow use CartSummary }

